captcha.cgi follows:
===
#!/usr/local/bin/perl -wT

use strict;

use lib qw(. lib);

use Bugzilla;
use Bugzilla::Constants;
use GD::SecurityImage;

my $dbh = Bugzilla->dbh;
my $cgi = Bugzilla->cgi;

my $captcha_cookie = $cgi->cookie( 'Captcha_cookie' );
my $captcha_value  = '';
if( defined( $captcha_cookie ) and length $captcha_cookie ){
        $captcha_value = $dbh->selectrow_array('select captcha from captcha where session = ?', undef, $captcha_cookie) or die $!;
}

my $image = GD::SecurityImage->new(
                width   => 80, height  => 30, lines   => 3, font => bz_locations()->{'datadir'}.'/fonts/VeraMono.ttf', rndmax => 3,
                ptsize  => 16,  send_ctobg      => 1,
);
$image->random( $captcha_value );
$image->create( 'ttf', 'default',  '#508090', '#0F644B' );
$image->particle( 800 );
print $cgi->header( -type => 'image/png', );

print $image->out( force => 'png' );
