Bug.* RPC namespace has many features but it's not able to close a bug?
Here is how I do it with add_comment. It takes resolution and bug_status parameters, same way as it is done in a process_bug.cgi:
===
--- Bugzilla/WebService/Bug.pm.orig     2010-12-20 18:15:21.000000000 +0300
+++ Bugzilla/WebService/Bug.pm  2010-12-20 18:15:35.000000000 +0300
@@ -504,6 +504,22 @@
     $bug->add_comment($comment, { isprivate => $params->{is_private},
                                   work_time => $params->{work_time} });

+    if (defined $params->{'bug_status'}) {
+        $bug->set_status(
+            scalar $params->{'bug_status'},
+            {resolution =>  scalar $params->{'resolution'},
+                dupe_of => scalar $params->{'dup_id'}
+            }
+        );
+    }
+    elsif (defined $params->{'resolution'} ) {
+        $bug->set_resolution(scalar $params->{'resolution'}, 
+                          {dupe_of => scalar $params->{'dup_id'});
+    }
+    elsif ( $params->{'dup_id'} ) {
+        $bug->set_dup_id( scalar $params->{'dup_id'} );
+    }
+
     # Capture the call to bug->update (which creates the new comment) in 
     # a transaction so we're sure to get the correct comment_id.

===

